from itertools import product
from math import exp
p={}
sig=lambda x:1/(1+exp(-x))
for h,v,c,r,y in product([0,1],repeat=5):
    phv=1/6 if h==v else 1/3
    pr=sig(.75*h+.5*c)
    py=sig(-.5+2.5*v+1.75*c)
    p[h,v,c,r,y]=phv*.5*(pr if r else 1-pr)*(py if y else 1-py)
def prob_y(**kw):
    ix={'h':0,'v':1,'c':2,'r':3}
    rows=[(state,w) for state,w in p.items() if all(state[ix[k]]==val for k,val in kw.items())]
    return sum(w for state,w in rows if state[4]==1)/sum(w for state,w in rows)
print('Exact probabilities under the manuscript simulation equations:')
for h in [0,1]:print(f'P(Y=1 | H={h}) = {prob_y(h=h):.6f}')
for c in [0,1]:
    for r in [0,1]:print(f'P(Y=1 | R={r}, C={c}) = {prob_y(r=r,c=c):.6f}')
print('Reported bird split sum:',2849+520+529)
print('Majority-label theoretical accuracy:',sum(w for state,w in p.items() if state[4]==1))
print('Bayes accuracy:',sum(w for state,w in p.items() if state[4]==(state[1] or state[2])))
PY"
